import type { LucideIcon } from "@lucide/svelte";
import type { Snippet } from "svelte";
import type { HTMLAttributes } from "svelte/elements";
import type { WithElementRef } from "$UTILS$";

export type ExperiencePositionItemType = {
	/** Unique identifier for the position. */
	id: string;
	/** The job title or position name. */
	title: string;
	/** Employment period. Use "MM.YYYY" or "YYYY" and omit `end` for current roles. */
	employmentPeriod: {
		/** Start date, for example "10.2022" or "2020". */
		start: string;
		/** End date; leave undefined for "Present". */
		end?: string;
	};
	/** The type of employment, for example "Full-time" or "Contract". */
	employmentType?: string;
	/** A Markdown description of the position or responsibilities. */
	description?: string;
	/** An icon representing the position. */
	icon?: LucideIcon;
	/** Skills associated with the position. */
	skills?: string[];
	/** Whether the position details are expanded initially. */
	isExpanded?: boolean;
};

export type ExperienceItemType = {
	/** Unique identifier for the experience item. */
	id: string;
	/** Name of the company where the experience was gained. */
	companyName: string;
	/** URL or path to the company's logo image. */
	companyLogo?: string;
	/** URL to the company's website. */
	companyWebsite?: string;
	/** Positions held at the company. */
	positions: ExperiencePositionItemType[];
	/** Whether this is the current employer. */
	isCurrentEmployer?: boolean;
};

export type WorkExperienceProps = WithElementRef<
	Omit<HTMLAttributes<HTMLDivElement>, "children">
> & {
	experiences: ExperienceItemType[];
};

export type ExperienceItemProps = {
	experience: ExperienceItemType;
};

export type ExperiencePositionItemProps = {
	position: ExperiencePositionItemType;
};

export type ProseProps = WithElementRef<
	Omit<HTMLAttributes<HTMLDivElement>, "children">
> & {
	children: Snippet;
};

export type SkillProps = WithElementRef<
	Omit<HTMLAttributes<HTMLSpanElement>, "children">
> & {
	children: Snippet;
};

import { differenceInMonths, parse } from "date-fns";

export function formatDuration(start: string, end?: string): string {
	const startHasMonth = start.includes(".");
	const endHasMonth = end ? end.includes(".") : true;

	if (!startHasMonth && end && !endHasMonth) {
		const years = Number.parseInt(end, 10) - Number.parseInt(start, 10);
		return years > 0 ? `${years}y` : "";
	}

	const startDate = parsePeriodDate(start, "first");
	const endDate = end ? parsePeriodDate(end, "last") : new Date();
	const totalMonths = differenceInMonths(endDate, startDate) + 1;

	if (totalMonths <= 0) return "";
	if (totalMonths < 12) return `${totalMonths}m`;

	const years = Math.floor(totalMonths / 12);
	const months = totalMonths % 12;

	return months === 0 ? `${years}y` : `${years}y ${months}m`;
}

function parsePeriodDate(value: string, fallbackMonth: "first" | "last"): Date {
	if (value.includes(".")) {
		return parse(value, "MM.yyyy", new Date());
	}

	const month = fallbackMonth === "last" ? "12" : "01";
	return parse(`${month}.${value}`, "MM.yyyy", new Date());
}

import ExperienceItem from "./experience-item.svelte";
import ExperiencePositionItem from "./experience-position-item.svelte";
import WorkExperience from "./work-experience.svelte";

export { ExperienceItem, ExperiencePositionItem, WorkExperience };

export type {
	ExperienceItemProps,
	ExperienceItemType,
	ExperiencePositionItemProps,
	ExperiencePositionItemType,
	ProseProps,
	SkillProps,
	WorkExperienceProps
} from "./work-experience-types";
